def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if nanoseconds is None:
        return None
    try:
        nanos = int(nanoseconds)
    except Exception:
        raise ValueError('nanoseconds must be an integer or convertible to int')

    # Compute seconds and remaining nanoseconds
    seconds_total = nanos // 1_000_000_000
    nano_remainder = nanos % 1_000_000_000
    if nano_remainder < 0:
        nano_remainder += 1_000_000_000
        seconds_total -= 1

    hours, rem = divmod(seconds_total, 3600)
    minutes, seconds = divmod(rem, 60)
    microseconds = nano_remainder // 1000

    if tz is not None:
        try:
            return datetime.datetime(1970, 1, 1, hours, minutes, seconds, microseconds, tzinfo=tz)
        except Exception as e:
            raise ValueError('tz must be a tzinfo object') from e
    else:
        try:
            return datetime.time(hours, minutes, seconds, microseconds)
        except Exception as e:
            raise ValueError('Failed to create time object') from e

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    # Prefer ISO format if the value provides it
    try:
        return value.isoformat()
    except AttributeError:
        pass
    # Fallback to constructing a HH:MM:SS string using duck typing
    try:
        hour = getattr(value, "hour")
        minute = getattr(value, "minute")
        second = getattr(value, "second", 0)
        # Include microseconds if present
        microsecond = getattr(value, "microsecond", None)
        if microsecond:
            return f"{hour:02d}:{minute:02d}:{second:02d}.{microsecond:06d}"
        return f"{hour:02d}:{minute:02d}:{second:02d}"
    except Exception as exc:
        raise TypeError("dehydrate_time expects a time-like object") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict representation of the Point
    """
    if value is None:
        return None
    # Verify that value looks like a Point instance
    required_attrs = ('lat', 'lon', 'time')
    if not all(hasattr(value, attr) for attr in required_attrs):
        raise TypeError('Expected a Point instance with lat, lon, and time attributes.')
    # Convert datetime to ISO format if it's a datetime object
    time_val = value.time
    try:
        iso_time = time_val.isoformat()
    except AttributeError:
        iso_time = str(time_val)
    return {
        'lat': value.lat,
        'lon': value.lon,
        'time': iso_time
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Ensure the internal cache exists
    try:
        if self._keys is None:
            # Attempt to populate the cache if a method exists
            if hasattr(self, "_list_keys") and callable(self._list_keys):
                self._list_keys()
    except Exception:
        # Gracefully handle any unexpected issue during cache population
        return []

    # If no keys are cached, return an empty list
    if not getattr(self, "_keys", {}):
        return []

    # If the cached values are Key objects with a 'name' attribute, extract names
    try:
        values = self._keys.values()
        if all(hasattr(v, "name") for v in values):
            return [v.name for v in values]
    except Exception:
        # Fallback to return raw keys (keys of the dict)
        pass

    # Default: return the dictionary keys
    try:
        return list(self._keys.keys())
    except Exception:
        return []

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        if len(protocol_version) != 2 or not all(isinstance(i, int) for i in protocol_version):
            raise TypeError("protocol_version must be a tuple of two integers")

    handlers = {}

    def _collect_subclasses(c):
        for sub in c.__subclasses__():
            yield sub
            yield from _collect_subclasses(sub)

    for handler_cls in _collect_subclasses(cls):
        vt = getattr(handler_cls, "_protocol_version", None)
        if (
            isinstance(vt, tuple)
            and len(vt) == 2
            and all(isinstance(i, int) for i in vt)
        ):
            handlers[vt] = handler_cls

    if protocol_version is not None:
        return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}
    return handlers

def unit_of_work(metadata=None, timeout=None):
    """This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.
    See the extensive docstring above."""
    from functools import wraps

    # Validate metadata and timeout upfront
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a numeric type or None")
        if timeout < 0:
            raise ValueError("timeout cannot be negative")
        timeout = float(timeout)

    def _decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # The first positional argument is expected to be a neo4j.Session instance
            if not args:
                raise TypeError("Missing session argument for transaction execution.")
            session = args[0]
            if not hasattr(session, "execute_transaction"):
                raise TypeError("First argument must be a Neo4j Session.")

            # Build the transaction configuration if needed
            config = {}
            if metadata is not None:
                config["metadata"] = metadata
            if timeout is not None:
                config["timeout"] = timeout

            # Define the inner function that will be passed to execute_transaction
            def _inner(tx, *inner_args, **inner_kwargs):
                return func(tx, *inner_args, **inner_kwargs)

            # Execute the transaction with the desired configuration
            try:
                # Pass along any additional positional and keyword arguments
                return session.execute_transaction(
                    _inner,
                    *args[1:],  # Remaining arguments after the session
                    **kwargs,
                    transaction_config=config or None  # None if config empty
                )
            except Exception as e:
                # Log the exception if a logger is available, otherwise re-raise
                try:
                    import logging
                    logger = logging.getLogger(__name__)
                    logger.exception("Transaction execution failed: %s", e)
                except Exception:
                    pass
                raise

        return wrapper

    return _decorator

