    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Argument must be a string")
    # Split the input on dots and attempt to extract the numeric components.
    parts = s.split('.')
    nums: list[int] = []
    for part in parts:
        if not part:
            continue
        # Grab the leading digits of each component.
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            try:
                nums.append(int(num_str))
            except ValueError:
                # Skip non-numeric parts that could not be converted.
                continue
    if not nums:
        # Return a single zero to avoid empty tuples in comparisons.
        return (0,)
    return tuple(nums)

