        return _update_wrapper(wrapper, func)

    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize is not None and maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if ttl <= 0:
        raise ValueError("ttl must be a positive value")

    def decorator(func):
        if not callable(func):
            raise ValueError("ttl_cache can only be applied to callables")
        from collections import OrderedDict
        cache = OrderedDict()

        def make_key(args, kwargs):
            if typed:
                # Include argument types for distinction
                key = args + tuple((k, v, type(v)) for k, v in sorted(kwargs.items()))
            else:
                key = args + tuple(sorted(kwargs.items()))
            return key

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            entry = cache.get(key)
            if entry is not None:
                value, expire = entry
                if expire > now:
                    # Move to end to indicate recent use
                    cache.move_to_end(key)
                    return value
                else:
                    # Expired entry
                    del cache[key]
            result = func(*args, **kwargs)
            expire_at = now + ttl
            cache[key] = (result, expire_at)
            cache.move_to_end(key)
            if maxsize is not None and len(cache) > maxsize:
                # Pop the least-recently used item
                cache.popitem(last=False)
            return result

        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    """
    Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(fn):
        if maxsize <= 0:
            raise ValueError("maxsize must be greater than zero")

        cache = OrderedDict()

        def make_key(*args, **kwargs):
            if typed:
                key = tuple((arg, type(arg)) for arg in args)
                kw_key = tuple((k, kwargs[k], type(kwargs[k])) for k in sorted(kwargs))
                return (key, kw_key)
            else:
                key = args
                kw_key = tuple(sorted(kwargs.items()))
                return (key, kw_key)

        @wraps(fn)
        def wrapper(*args, **kwargs):
            k = make_key(*args, **kwargs)
            if k in cache:
                cache.move_to_end(k, last=True)
                return cache[k]
            result = fn(*args, **kwargs)
            cache[k] = result
            cache.move_to_end(k, last=True)
            if len(cache) > maxsize:
                # Remove the most recently used item
                cache.popitem(last=True)
            return result

        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorator(fn):
        return functools.lru_cache(maxsize=maxsize, typed=typed)(fn)
    return decorator

def lfu_cache(maxsize=128, typed=False):
    def decorator(fn):
        if maxsize <= 0:
            # No caching - just return the original function
            def wrapper(*args, **kwargs):
                return fn(*args, **kwargs)
            return wrapper

        cache = {}
        freq = {}

        def _make_key(args, kwargs):
            if kwargs:
                kw = tuple(sorted(kwargs.items()))
            else:
                kw = ()
            if typed:
                # Include types to differentiate values of different types
                kwtype = tuple(map(type, kw))
                argtype = tuple(map(type, args))
                return args + kw + argtype + kwtype
            return args + kw

        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            if key in cache:
                freq[key] += 1
                return cache[key]
            result = fn(*args, **kwargs)
            if len(cache) >= maxsize:
                # Evict the least frequently used entry.
                # In case of ties, evict an arbitrary one.
                minfreq = min(freq.values())
                # Find a key with this minimal frequency
                for evict_key, f in freq.items():
                    if f == minfreq:
                        break
                del cache[evict_key]
                del freq[evict_key]
            cache[key] = result
            freq[key] = 1
            return result

        # expose cache clear method similar to lru_cache
        def cache_clear():
            cache.clear()
            freq.clear()

        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        first_key = next(iter(self))
        first_value = self[first_key]
        del self[first_key]
        return (first_key, first_value)
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')

