def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean")

    import inspect
    names_desc = []
    # Determine which classes to inspect
    classes = inspect.getmro(self.__class__) if all else [self.__class__]
    seen = set()
    for cls in classes:
        for name, obj in cls.__dict__.items():
            # Avoid duplicate names from base classes
            if name in seen:
                continue
            seen.add(name)
            if name.startswith('_'):
                continue
            # Skip callables and class/static methods
            if callable(obj):
                continue
            if isinstance(obj, (staticmethod, classmethod)):
                continue
            desc = ''
            # Attempt to get a docstring
            if hasattr(obj, '__doc__') and obj.__doc__:
                desc = obj.__doc__
            names_desc.append((name, desc))
    return names_desc

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("`all` must be a boolean value")
    # In the non-all case, we return the instance's own attributes
    if not all:
        return sorted(name for name in getattr(self, "__dict__", {})
                      if not name.startswith('_'))
    # In the all case, include attributes from the entire MRO, excluding dunder
    names = set()
    for cls in self.__class__.mro():
        names.update(name for name in getattr(cls, "__dict__", {})
                     if not name.startswith('_'))
    return sorted(names)

