def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # If seq itself is a FillRequest, it's a valid single element
        if isinstance(seq, FillRequest):
            return True
        # Reject Source sequences explicitly
        if isinstance(seq, Source):
            return False
        # Attempt to iterate over seq and look for any FillRequest instances
        for element in seq:
            if isinstance(element, FillRequest):
                return True
        return False
    except Exception:
        # On any error (e.g., non‑iterable seq) consider it not a valid FillRequestSeq
        return False

