            return {}
        diff = {}
        for k, v1 in dict1.items():
            if k not in dict2:
                diff[k] = v1 if not isinstance(v1, dict) else _diff(v1, {}, depth - 1)
            else:
                v2 = dict2[k]
                if isinstance(v1, dict) and isinstance(v2, dict):
                    sub = _diff(v1, v2, depth - 1)
                    if sub:
                        diff[k] = sub
                else:
                    if v1 != v2:
                        diff[k] = v1
        return diff
    return _diff(d1, d2, max_depth)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise TypeError("coord must be array‑like") from exc

    if coord_arr.ndim != 1:
        raise ValueError("coord must be a 1‑D array matching the histogram dimensions")

    n_dims = len(self.edges)
    if coord_arr.size != n_dims:
        raise ValueError(f"coord length {coord_arr.size} does not match histogram dimensions {n_dims}")

    # Determine bin indices; ignore if any coordinate is out of bounds
    idxs = []
    for dim, c in enumerate(coord_arr):
        edges = self.edges[dim]
        if c < edges[0] or c >= edges[-1]:
            return  # Outside histogram bounds; ignore
        idx = np.searchsorted(edges, c, side='right') - 1
        idxs.append(idx)

    # Update the corresponding bin
    try:
        self.values[tuple(idxs)] += weight
    except Exception as exc:
        raise RuntimeError("Failed to update histogram bin") from exc

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.

    Returns:
        The updated ``last_applied_manifest`` (in place) for convenience.
    """
    # Defensive copy to avoid None errors
    if last_applied_manifest is None:
        last_applied_manifest = {}
    if response is None:
        response = {}

    try:
        for field in observer_schema:
            # Support simple string field names or dict descriptions
            if isinstance(field, str):
                key = field
                sub_schema = None
            elif isinstance(field, dict):
                key = field.get("name")
                sub_schema = field.get("schema")
            else:
                # Unexpected schema element; skip
                continue

            if key is None:
                continue

            # If the key exists in the response, propagate its value
            if key in response:
                val = response[key]
                # If there is a schema for this field, recurse appropriately
                if sub_schema:
                    if isinstance(val, dict):
                        sub_manifest = last_applied_manifest.get(key, {})
                        try:
                            from .update_last_applied_manifest_dict_from_resp import (
                                update_last_applied_manifest_dict_from_resp,
                            )
                        except Exception:  # pragma: no cover
                            # If the import fails, just continue
                            sub_manifest = val
                        else:
                            update_last_applied_manifest_dict_from_resp(
                                sub_manifest, sub_schema, val
                            )
                        last_applied_manifest[key] = sub_manifest
                    elif isinstance(val, list):
                        sub_manifest = last_applied_manifest.get(key, [])
                        try:
                            from .update_last_applied_manifest_list_from_resp import (
                                update_last_applied_manifest_list_from_resp,
                            )
                        except Exception:  # pragma: no cover
                            sub_manifest = val
                        else:
                            update_last_applied_manifest_list_from_resp(
                                sub_manifest, sub_schema, val
                            )
                        last_applied_manifest[key] = sub_manifest
                    else:
                        # Scalar field with a schema that is not dict/list
                        if key not in last_applied_manifest:
                            last_applied_manifest[key] = val
                else:
                    # No schema; simply copy over the value if not already present
                    if key not in last_applied_manifest:
                        last_applied_manifest[key] = val
            else:
                # Key is absent in the response; do not modify last_applied_manifest
                continue
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(
            f"Failed to update last applied manifest list from response: {exc}"
        ) from exc

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present

    """
    for key, schema_val in observer_schema.items():
        if key not in response:
            raise KeyError(
                f"Observed field '{key}' not present in the Kubernetes response"
            )
        resp_val = response[key]
        # If the schema entry is a dict, recurse into dict
        if isinstance(schema_val, dict):
            sub_dict = last_applied_manifest.get(key)
            if sub_dict is None or not isinstance(sub_dict, dict):
                sub_dict = {}
                last_applied_manifest[key] = sub_dict
            update_last_applied_manifest_dict_from_resp(
                sub_dict, schema_val, resp_val
            )
        # If the schema entry is a list, handle list-specific update
        elif isinstance(schema_val, list):
            sub_list = last_applied_manifest.get(key)
            if sub_list is None or not isinstance(sub_list, list):
                sub_list = []
                last_applied_manifest[key] = sub_list
            # Assume a helper function exists for list updates
            update_last_applied_manifest_list_from_resp(
                sub_list, schema_val, resp_val
            )
        else:
            # Primitive field: set only if not already present
            if key not in last_applied_manifest:
                last_applied_manifest[key] = resp_val
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the application has the expected attributes
    try:
        manifest = app.spec.manifest
    except AttributeError as exc:
        raise ValueError(
            "The provided application does not expose a 'spec.manifest' attribute"
        ) from exc

    # Use existing observer schemas if present, otherwise start with an empty dict
    observer_schemas = getattr(app.spec, "observer_schemas", {})
    if observer_schemas is None:
        observer_schemas = {}

    # Compile a set of kinds already handled by custom schemas
    handled_kinds = set(observer_schemas.keys())

    # Iterate through each resource in the manifest
    for resource in manifest:
        # Handle dictionary resources that contain a 'kind' field
        if isinstance(resource, dict) and "kind" in resource:
            kind = resource["kind"]
        else:
            # If the entry is not in the expected format, skip it
            continue

        if not kind or kind in handled_kinds:
            continue

        # Assemble a very basic default observer schema
        default_schema = {
            "type": "object",
            "properties": {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {"type": "string"},
                        "namespace": {"type": "string"},
                    },
                },
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
        }

        # Register the default schema for this kind
        observer_schemas[kind] = default_schema

    # Persist the updated schema mapping back to the spec if it exists
    if hasattr(app.spec, "observer_schemas"):
        app.spec.observer_schemas = observer_schemas

    return observer_schemas

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    # Retrieve the log; allow for attribute missing or any iterable
    log = getattr(self, 'log', None)
    if isinstance(log, (list, tuple)):
        lines = log
    elif isinstance(log, str):
        # Treat a single string as a list of lines
        lines = log.splitlines()
    else:
        # If log is missing or not iterable, use a placeholder
        lines = [str(log)] if log is not None else []
    # Build the combined string
    try:
        body = "\n".join(str(line) for line in lines)
    except Exception:
        # Fallback: representation of the log object
        body = str(log)
    return prefix + body if body else prefix

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Normalise inventory structure
    source = inventory
    if isinstance(inventory, dict) and 'data' in inventory:
        source = inventory['data']

    if not isinstance(source, dict):
        raise TypeError('Inventory must be a dict or dict with a "data" key')

    # Check that the requested version exists
    if version not in source:
        raise ValueError(f'Version {version!r} not found in inventory')

    # Helper to determine if a version should be considered (>= requested)
    def version_ge(v, req):
        try:
            return v >= req
        except Exception:  # e.g., incomparable types
            return False

    logical_map = {}

    for ver, state in source.items():
        # Skip versions that are earlier than requested
        try:
            if not version_ge(ver, version):
                continue
        except Exception:
            # If we cannot compare, skip this entry
            continue

        if not isinstance(state, dict):
            continue

        for logical_path, content in state.items():
            if logical_path not in logical_map:
                logical_map[logical_path] = set()
            # Ensure content is iterable of file paths
            if isinstance(content, (list, tuple, set)):
                logical_map[logical_path].update(content)
            else:
                # Treat non-iterable as single path
                logical_map[logical_path].add(content)

    return logical_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError(
                f"Fixity block must be a dict, got {type(fixity).__name__}"
            )
        # Ensure manifest_files is iterable of strings
        try:
            manifest_set = set(str(name) for name in manifest_files)
        except TypeError:
            raise ValueError(
                "manifest_files must be an iterable of file names"
            )
        # Iterate over each entry in the fixity block
        for file_name, entry in fixity.items():
            if file_name not in manifest_set:
                raise ValueError(
                    f"Fixity entry references unknown file '{file_name}'."
                )
            if not isinstance(entry, dict):
                raise ValueError(
                    f"Fixity entry for '{file_name}' must be a dict, "
                    f"got {type(entry).__name__}"
                )
            # Expected keys in each fixity entry
            for key in ("checksum", "algorithm"):
                if key not in entry:
                    raise ValueError(
                        f"Missing '{key}' in fixity entry for '{file_name}'."
                    )
                if not isinstance(entry[key], str):
                    raise ValueError(
                        f"'{key}' for '{file_name}' must be a string."
                    )
        # If all checks pass, return True (optional)
        return True

def files_list(path):
    """
    Return the files in `path`
    """
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    result = []
    if os.path.isfile(path):
        result.append(os.path.abspath(path))
    elif os.path.isdir(path):
        for entry in os.listdir(path):
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path):
                result.append(os.path.abspath(full_path))
    return result

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`."""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                return result[0]
        except Exception:
            continue
    return None

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        import importlib
        mod = importlib.import_module("version")
        return getattr(mod, "__version__", default)
    except Exception:
        return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, dict):
        raise TypeError("pieces must be a dict")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()
    try:
        major = str(pieces.get("major", 0))
        minor = str(pieces.get("minor", 0))
        patch = str(pieces.get("patch", 0))
        prerelease = pieces.get("prerelease", "")
        build = pieces.get("build", "")
        base = f"{major}.{minor}.{patch}"
        if style == "semver":
            result = base
            if prerelease:
                result += f"-{prerelease}"
            if build:
                result += f"+{build}"
            return result
        if style == "short":
            return f"{major}.{minor}"
        if style == "full":
            return base
        if style == "compact":
            if patch == "0":
                return f"{major}.{minor}"
            return base
        if style == "pre_release":
            if prerelease:
                return f"{base}-{prerelease}"
            return base
        raise ValueError(
            f"Unsupported style '{style}'. Supported styles: semver, short, full, compact, pre_release"
        )
    except Exception as exc:
        raise ValueError("Failed to render version pieces") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import sys

    # Prepare command line list
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        cmd_list = [commands]

    if args:
        if isinstance(args, (list, tuple)):
            cmd_list.extend(args)
        else:
            cmd_list.append(args)

    # Verbose output
    if verbose:
        print('Running command:', ' '.join(cmd_list), file=sys.stderr)

    # Determine stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        output = subprocess.check_output(
            cmd_list,
            cwd=cwd,
            env=env,
            stderr=stderr,
            shell=False
        )
        # Decode output to string
        if isinstance(output, bytes):
            output = output.decode('utf-8')
    except subprocess.CalledProcessError as e:
        # Re-raise the error with a clear message
        raise subprocess.CalledProcessError(e.returncode, e.cmd, output=output if 'output' in dir(e) else None)

    return output.strip() if output is not None else ''

def register_vcs_handler(vcs, method):  # type: (str, str) -> typing.Callable
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if not isinstance(vcs, str) or not isinstance(method, str):
            raise TypeError("vcs and method must be strings")
        try:
            global HANDLERS  # assumes HANDLERS is defined elsewhere
            HANDLERS.setdefault(vcs, {})[method] = f
        except Exception as exc:
            raise RuntimeError("Failed to register VCS handler") from exc
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        import hashlib
        num_objects = 0
        good_objects = 0

        # Determine where the objects are stored; fall back to empty list if not present
        try:
            objects = self.objects
        except AttributeError:
            objects = []

        for obj in objects:
            num_objects += 1
            is_valid = True

            # Optional structural validation
            if validate_objects:
                try:
                    if hasattr(obj, "validate"):
                        obj.validate()
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARNING] Validation error for object {obj}: {exc}")

            # Optional digest validation
            if check_digests and is_valid:
                try:
                    if hasattr(obj, "content") and hasattr(obj, "digest"):
                        content = obj.content
                        if isinstance(content, bytes):
                            computed = hashlib.sha256(content).hexdigest()
                        else:
                            computed = hashlib.sha256(str(content).encode()).hexdigest()
                        if computed != obj.digest:
                            is_valid = False
                            if show_warnings:
                                print(f"[WARNING] Digest mismatch for object {obj}")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARNING] Digest check failed for object {obj}: {exc}")

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""

    version = version.strip()
    if not version:
        return ""

    parts = version.split('.')
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        # If any component cannot be parsed as an integer, return original.
        return version

    # Increment the last component
    nums[-1] += 1

    new_parts = []
    for orig, new_val in zip(parts, nums):
        # Preserve leading zeros if the original part had them
        if orig[0] == '0' and len(orig) > 1:
            new_part = str(new_val).zfill(len(orig))
        else:
            new_part = str(new_val)
        new_parts.append(new_part)

    return '.'.join(new_parts)

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        import re
    except Exception as exc:
        return f'internal error: {exc}'

    if not isinstance(path, str):
        return f'path must be a string, got {type(path).__name__}'

    if not os.path.exists(path):
        return f'path does not exist: {path}'

    if os.path.isfile(path):
        return 'file'

    if not os.path.isdir(path):
        return f'unsupported path type: {path}'

    try:
        entries = os.listdir(path)
    except Exception as exc:
        return f'cannot list directory {path}: {exc}'

    # look for Namaste files that start with '0='
    namaste_files = [e for e in entries if re.match(r'^0=.*', e)]
    if namaste_files:
        return 'object'

    # if directory contains subdirectories, treat as a storage root
    if any(os.path.isdir(os.path.join(path, d)) for d in entries):
        return 'root'

    # empty directory or only files not matching '0='
    if entries:
        return f'unknown dir content, entries={entries}'
    return f'empty directory: {path}'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    # Normalize bug_ids to a list
    if isinstance(bug_ids, (list, tuple, set)):
        to_add = list(bug_ids)
    else:
        to_add = [bug_ids]
    # Merge into the 'ids' key
    if "ids" in params:
        existing = params["ids"]
        if isinstance(existing, (list, tuple)):
            existing_list = list(existing)
        else:
            existing_list = [existing]
        existing_list.extend(to_add)
        params["ids"] = existing_list
    else:
        params["ids"] = to_add
    return params

