def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string.
    '''
    try:
        # validate parser
        if not hasattr(parser, '_actions'):
            raise TypeError("Expected an argparse.ArgumentParser instance")
        flags = []
        for action in parser._actions:
            # Only include actions that have explicit option strings (e.g., -f, --flag)
            if getattr(action, 'option_strings', None):
                flags.extend(action.option_strings)
        return " ".join(flags)
    except Exception:
        # In case of any unexpected issue, return an empty string
        return ""

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    unknown_sets = []
    try:
        for name, parser in subparsers.items():
            ns, unknown = parser.parse_known_args(list(unparsed_arguments))
            parsed[name] = ns
            unknown_sets.append(set(unknown))
    except Exception as exc:
        # If parsing fails for any subparser, return what we have so far with the original arguments
        return parsed, list(unparsed_arguments)
    if unknown_sets:
        remaining = list(set.intersection(*unknown_sets))
    else:
        remaining = list(unparsed_arguments)
    return parsed, remaining

def deep_merge_nodes(nodes):
    '''
    Deep merge a list of (key, value) node tuples, combining MappingNode values for duplicate keys.
    '''
    try:
        from ruamel.yaml.nodes import MappingNode
    except Exception as exc:
        raise RuntimeError('ruamel.yaml.nodes.MappingNode required') from exc

    def _merge_mapping_nodes(node1, node2):
        merged_entries = {}
        order = []

        def _store(k_node, v_node):
            key = k_node.value
            if key in merged_entries:
                existing_k_node, existing_v_node = merged_entries[key]
                if isinstance(existing_v_node, MappingNode) and isinstance(v_node, MappingNode):
                    merged_val = _merge_mapping_nodes(existing_v_node, v_node)
                else:
                    merged_val = v_node
                merged_entries[key] = (existing_k_node, merged_val)
            else:
                merged_entries[key] = (k_node, v_node)
                order.append(key)

        for k, v in node1.value:
            _store(k, v)
        for k, v in node2.value:
            _store(k, v)

        return MappingNode(node1.tag, [merged_entries[k] for k in order])

    result = {}
    order = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key in result:
            existing_key, existing_val = result[key]
            if isinstance(existing_val, MappingNode) and isinstance(value_node, MappingNode):
                merged_val = _merge_mapping_nodes(existing_val, value_node)
            else:
                merged_val = value_node
            result[key] = (existing_key, merged_val)
        else:
            result[key] = (key_node, value_node)
            order.append(key)

    return [result[k] for k in order]

def parse_arguments(*arguments):
    """Given command-line arguments with which this script was invoked, parse the arguments and return them as an ArgumentParser instance."""
    import argparse
