def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # If parser is None, return an empty string
    if parser is None:
        return ""

    # Verify that the object behaves like an argparse.ArgumentParser
    try:
        actions = parser._actions
    except AttributeError as exc:
        raise TypeError("parser must be an argparse.ArgumentParser instance") from exc

    flags = []
    for action in actions:
        # Some actions may not implement option_strings; skip them
        try:
            flags.extend(action.option_strings)
        except AttributeError:
            continue

    # Preserve order while removing duplicates
    seen = set()
    unique_flags = []
    for flag in flags:
        if flag not in seen:
            seen.add(flag)
            unique_flags.append(flag)

    return " ".join(unique_flags)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for k, v in d.items():
            if k in result:
                try:
                    result[k] += v
                except TypeError as exc:
                    raise TypeError(f"Cannot sum values for key {k!r}: {exc}") from exc
            else:
                result[k] = v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    import re
    from collections.abc import Mapping

    if not isinstance(url_args, Mapping):
        raise TypeError(f'url_args must be a mapping, got {type(url_args).__name__}')

    if not url:
        return url

    # Pattern matches {key} where key consists of alphanumerics and underscores
    pattern = re.compile(r'{(?P<key>[a-zA-Z0-9_]+)}')

    def _replace(match):
        key = match.group('key')
        if key in url_args:
            # Convert the value to string; do not perform URL encoding here
            return str(url_args[key])
        # If key not provided, leave placeholder unchanged
        return match.group(0)

    try:
        return pattern.sub(_replace, url)
    except Exception as exc:
        # In case of unexpected error, log and return original URL
        # Assuming a logger named 'logger' is available; if not, ignore
        try:
            logger = globals().get('logger')
            if logger:
                logger.warning(f'Error replacing URL args for {url!r}: {exc!s}')
        except Exception:
            pass
        return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if val is None:
            return True
        if isinstance(val, str):
            stripped = val.strip()
            if not stripped:
                return True
            lowered = stripped.lower()
            return lowered in ("none", "null", "n/a", "na")
        return False
    except Exception:
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if not hasattr(parser, '_actions'):
        raise TypeError('Expected an argparse.ArgumentParser instance.')

    flags = []
    # Iterate in the order actions were added
    for action in parser._actions:
        # `option_strings` contains the flag names for optional arguments
        if action.option_strings:
            flags.extend(action.option_strings)

    return ' '.join(flags)

def vertex3tuple(vertices):
    """
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::
        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        if not isinstance(vertices, list):
            raise TypeError("vertices must be a list")
        n = len(vertices)
        if n == 0:
            return []
        res = []
        for i in range(n):
            prev = vertices[i - 1] if i != 0 else vertices[-1]
            curr = vertices[i]
            nxt = vertices[(i + 1) % n]
            res.append((prev, curr, nxt))
        return res
    except Exception as e:
        raise ValueError(f"Error computing vertex triples: {e}")

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic type checks
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two symbols")
    if any(not isinstance(ch, str) for ch in alphabet):
        raise TypeError("alphabet elements must be strings")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet elements must be unique")

    # Validate number
    if number < 0:
        raise ValueError("number must be non‑negative")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits.reverse()
        result = ''.join(digits)

    # Handle padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non‑negative integer or None")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    # Basic validation to avoid silent errors
    if value is None or arg is None:
        raise ValueError("Both 'value' and 'arg' must be provided and not None.")
    if not isinstance(value, str):
        raise TypeError(f"Expected 'value' to be a str, got {type(value).__name__}.")
    if not isinstance(arg, str):
        raise TypeError(f"Expected 'arg' to be a str, got {type(arg).__name__}.")

    try:
        # Replace every '.' with the provided argument string
        return value.replace('.', arg)
    except Exception as exc:
        # Provide a clear message in case of unexpected errors
        raise RuntimeError(f"Failed to replace dots: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        for sub in getattr(current, "__subclasses__", lambda: [])():
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    seen.discard(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two characters.")
    # Build a mapping from character to its positional value
    digit_map = {char: idx for idx, char in enumerate(alphabet)}
    number = 0
    for char in string:
        if char not in digit_map:
            raise ValueError(f"Character {char!r} not in alphabet.")
        number = number * base + digit_map[char]
    return number

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.
    """
    if not isinstance(item, dict):
        raise TypeError("Input must be a dictionary")
    regexed = {}
    for key, value in item.items():
        if not isinstance(key, str):
            raise TypeError("Dictionary keys must be strings")
        try:
            # Escape regex meta-characters except for glob wildcards
            pattern = re.escape(key)
            # Replace glob wildcards with regex equivalents
            pattern = pattern.replace(r'\*', '.*').replace(r'\?', '.')
            # Anchor pattern to match whole string
            pattern = '^' + pattern + '$'
            regexed[pattern] = value
        except re.error as exc:
            raise ValueError(f"Invalid regex conversion for key '{key}': {exc}") from exc
    return regexed

def unquote(name):
    """Remove quote from the given name."""
    if name is None:
        return None
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    # Unescape common escaped quote sequences
    cleaned = name.replace('\\"', '"').replace("\\'", "'").replace('\\\\\\', '\\')
    # Remove surrounding matching quotes if present
    if len(cleaned) >= 2 and cleaned[0] == cleaned[-1] and cleaned[0] in ('"', "'", '<', '>'):
        return cleaned[1:-1]
    return cleaned

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os, sys

    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1
    if not isinstance(s, (str, bytes)):
        raise TypeError(f's must be a string, not {type(s).__name__}')
    if isinstance(s, bytes):
        try:
            s = s.decode(sys.getdefaultencoding())
        except Exception as exc:
            raise ValueError('Cannot decode bytes input') from exc

    if platform == 1:
        # Simplified POSIX split
        if not s:
            return []

        token_re = re.compile(r'''
            (?:                 # start token
                "(?:[^"\\]|\\.)*"   # quoted double
                |'(?:[^'\\]|\\.)*'   # quoted single
                |[^ \t\r\n]+        # unquoted
            )
            ''', re.VERBOSE)
        parts = []
        for match in token_re.finditer(s):
            token = match.group(0)
            if token[0] in ('"', "'"):
                # strip quotes and unescape
                token = token[1:-1]
                token = re.sub(r'\\(.)', r'\1', token)
            parts.append(token)
        return parts

    elif platform == 0:
        # Simplified Windows CMD split
        if not s:
            return []

        win_re = re.compile(r'''
            (?:                           # token
                "(?:[^"\\]|\\.)*"         # quoted
                |[^ \t]+                  # unquoted
            )
            ''', re.VERBOSE)
        parts = []
        for match in win_re.finditer(s):
            token = match.group(0)
            if token[0] == '"':
                # remove surrounding quotes
                token = token[1:-1]
                # unescape \\
                token = re.sub(r'\\(.)', r'\1', token)
            parts.append(token)
        return parts

    else:
        raise ValueError(f'Unsupported platform value: {platform}')

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if args is None:
        args = []
    # Helper to run a single command list
    def _run(cmd_list):
        if verbose:
            print("Running:", " ".join(map(str, cmd_list)))
        try:
            result = subprocess.run(
                cmd_list,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                check=True,
                text=True,
            )
            return result
        except subprocess.CalledProcessError as exc:
            raise RuntimeError(
                f"Command '{' '.join(exc.cmd)}' failed with exit code {exc.returncode}"
            ) from exc
    # If commands is an iterable of commands, run them sequentially
    if isinstance(commands, (list, tuple)):
        results = []
        for cmd in commands:
            if isinstance(cmd, (list, tuple)):
                cmd_list = list(cmd) + list(args)
            else:
                cmd_list = [cmd] + list(args)
            results.append(_run(cmd_list))
        return results
    # Otherwise treat as a single command
    cmd_list = [commands] + list(args)
    return _run(cmd_list)

def is_ipv4(target):
    """Check if the given target is a valid IPv4 address."""
    # Accept already parsed IPv4Address objects directly
    if isinstance(target, ipaddress.IPv4Address):
        return True
    try:
        # Attempt to parse the target; raises ValueError or TypeError on failure
        ipaddress.IPv4Address(target)
    except (ValueError, TypeError):
        return False
    return True

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is not None and not isinstance(dumper, type):
        raise TypeError("dumper must be a class derived from yaml.Dumper")
    try:
        if dumper is None:
            yaml_str = yaml.safe_dump(obj, default_flow_style=False)
        else:
            yaml_str = yaml.safe_dump(obj, Dumper=dumper, default_flow_style=False)
    except Exception as exc:
        raise ValueError("Could not serialize object to YAML string") from exc
    return yaml_str

def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate and normalize shape
    try:
        shape = tuple(int(dim) for dim in shape)
    except Exception as exc:
        raise ValueError(f"Shape must be a tuple/list of integers, got {shape}") from exc

    # Ensure dtype is a numpy dtype instance
    try:
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise ValueError(f"dtype must be a numpy dtype object, got {dtype}") from exc

    # Create the array
    try:
        return np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise ValueError(f"Could not create array with shape {shape} and dtype {dtype}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """

    mean = 0.2
    sigma = 0.1
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input x must be convertible to a NumPy array.") from e
    factor = 1.0/(sigma*np.sqrt(2*np.pi))
    exponent = -0.5 * ((arr - mean)/sigma)**2
    return factor * np.exp(exponent)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed
    configuration, and sequence of logging.LogRecord instances containing any parse errors.
    """
    parsed_configs = {}
    error_records = []
    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as fd:
                raw = fd.read()
            # Try JSON
            cfg = None
            try:
                cfg = json.loads(raw)
            except Exception:
                try:
                    cfg = yaml.safe_load(raw)
                except Exception:
                    try:
                        cfg = toml.loads(raw)
                    except Exception:
                        # All parsers failed
                        record = logging.LogRecord(
                            name='load_configurations',
                            level=logging.ERROR,
                            pathname=fname,
                            lineno=0,
                            msg=f"Failed to parse configuration file: {fname}",
                            args=None,
                            exc_info=None
                        )
                        error_records.append(record)
                        continue
            # Apply overrides if provided
            if overrides and isinstance(overrides, dict):
                cfg.update(overrides)
            # Resolve environment variables in string values
            if resolve_env:
                def _expand(obj):
                    if isinstance(obj, dict):
                        return {k: _expand(v) for k, v in obj.items()}
                    elif isinstance(obj, list):
                        return [_expand(v) for v in obj]
                    elif isinstance(obj, str):
                        return os.path.expandvars(obj)
                    else:
                        return obj
                cfg = _expand(cfg)
            parsed_configs[fname] = cfg
        except FileNotFoundError:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Configuration file not found: {fname}",
                args=None,
                exc_info=None
            )
            error_records.append(record)
        except Exception:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Error processing configuration file: {fname}",
                args=None,
                exc_info=None
            )
            error_records.append(record)
    return parsed_configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    # Return bytes unchanged
    if isinstance(obj, (bytes, numpy.string_)):
        return obj
    # Encode Python str or numpy unicode_ to UTF‑8 bytes
    if isinstance(obj, (str, numpy.unicode_)):
        # Convert numpy unicode_ to a Python str first if necessary
        text = str(obj)
        try:
            return text.encode('utf-8')
        except Exception:
            # If encoding fails, return the original object
            return obj
    # For all other types, just return the object unchanged
    return obj

def protocol_handlers(cls, protocol_version=None):
        """Return a dictionary of available Bolt protocol handlers.

        The dictionary is keyed by a version tuple.  If ``protocol_version`` is
        supplied and is supported, the dictionary will contain exactly that
        one entry; otherwise it will contain all supported entries.

        :param protocol_version: tuple identifying a specific protocol version
                                 (e.g. (3, 5)) or ``None``.
        :return: dictionary mapping version tuples to handler classes.
        :raise TypeError: if ``protocol_version`` is not ``None`` and not a tuple.
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple of (major, minor), got {type(protocol_version).__name__}"
            )

        # Expect a class attribute that holds all protocol handlers.
        # By convention we look for ``_protocol_handlers`` or ``protocol_handlers_dict``.
        registry = getattr(cls, "_protocol_handlers", None) or getattr(
            cls, "protocol_handlers_dict", None
        )
        if registry is None or not isinstance(registry, dict):
            # No handlers registered, return empty dict.
            return {}

        # Optionally filter out handlers that indicate they are not supported.
        # Many handlers will simply not set ``_supported``; in that case we
        # treat them as supported.  This allows the handler class to opt out
        # with an attribute ``_supported = False``.
        filtered = {
            ver: handler
            for ver, handler in registry.items()
            if getattr(handler, "_supported", True)
        }

        if protocol_version is None:
            return dict(filtered)

        # Return only the matched version, if it exists.
        return {protocol_version: filtered[protocol_version]} if protocol_version in filtered else {}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("The 'values' argument must not be None")

    try:
        iterator = iter(values)
    except TypeError as exc:
        raise TypeError("The 'values' argument must be an iterable of strings") from exc

    bookmarks = []
    for idx, v in enumerate(iterator, start=1):
        if not isinstance(v, str):
            raise TypeError(f"Bookmark at position {idx} must be a string, "
                            f"got {type(v).__name__}")
        bookmarks.append(v)

    # Instantiate a Bookmarks object, passing the validated list.
    # This relies on the Bookmarks constructor accepting a 'bookmarks'
    # keyword argument; adjust if the signature differs.
    return cls(bookmarks=bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""
    if seq is None:
        raise TypeError("seq must not be None")

    seq_type = type(seq)

    # If seq is already a list or tuple, use it as is
    if isinstance(seq, (list, tuple)):
        seq_seq = seq
    elif isinstance(seq, (str, bytes)):
        # strings and bytes are iterable but we want a list of characters
        seq_seq = list(seq)
    else:
        try:
            # Try to convert any other iterable to a list
            seq_seq = list(seq)
            # Note: the original type (e.g., generator) is preserved in seq_type
        except Exception as exc:
            raise TypeError(f"Provided sequence {seq!r} is not iterable") from exc

    if bufsize is not None:
        try:
            seq_seq = seq_seq[:bufsize]
        except Exception:
            # If seq_seq is not sliceable we ignore bufsize (unlikely with list)
            pass

    return seq_seq, seq_type

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate
    allowed_coords = {"left", "right", "middle"}
    if get_coordinate not in allowed_coords:
        raise ValueError(f"get_coordinate must be one of {allowed_coords}")

    # Determine histogram representation
    try:
        if hasattr(hist, "counts") and hasattr(hist, "bin_edges"):
            counts = hist.counts
            edges = hist.bin_edges
        elif isinstance(hist, dict) and "counts" in hist and "bin_edges" in hist:
            counts = hist["counts"]
            edges = hist["bin_edges"]
        elif isinstance(hist, tuple) and len(hist) == 2:
            counts, edges = hist
        else:
            raise TypeError("Unsupported histogram type")
    except Exception as exc:
        raise ValueError("Failed to extract histogram data") from exc

    if len(edges) - 1 != len(counts):
        raise ValueError("Number of edges must be one more than number of counts")

    # Default make_value function
    if make_value is None:
        make_value = lambda bin_: bin_

    # prepare graph points
    points = []
    for i, bin_content in enumerate(counts):
        left = edges[i]
        right = edges[i + 1]
        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        else:  # middle
            coord = (left + right) / 2.0

        try:
            val = make_value(bin_content)
        except Exception as exc:
            raise ValueError(f"make_value failed for bin content {bin_content}") from exc

        # Ensure val is iterable if more than one field
        if isinstance(val, (list, tuple)):
            if len(val) != len(field_names) - 1:
                raise ValueError(
                    f"make_value returned {len(val)} values, "
                    f"expected {len(field_names) - 1}"
                )
            point = {field_names[0]: coord}
            for fn, v in zip(field_names[1:], val):
                point[fn] = v
        else:
            if len(field_names) != 2:
                raise ValueError(
                    f"make_value returned a single value but field_names has "
                    f"{len(field_names)} entries"
                )
            point = {field_names[0]: coord, field_names[1]: val}

        points.append(point)

    # Determine scale
    final_scale = scale
    if scale is True:
        # Try to use histogram's scale if available
        final_scale = getattr(hist, "scale", None)

    # Return a simple graph representation
    return {"points": points, "scale": final_scale}

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Sanity checks for the provided arguments
    if iface is None or candidate is None:
        raise TypeError("Both 'iface' and 'candidate' must be provided")

    # Determine the class (or module) being checked
    # If candidate is a class, use it directly; otherwise use its type
    candidate_cls = candidate if isinstance(candidate, type) else getattr(candidate, "__class__", candidate)

    # Ensure iface is a class or a module-like object
    if not isinstance(iface, type) and not hasattr(iface, "__dict__"):
        raise TypeError("'iface' must be a class or provide a '__dict__' attribute")

    # Collect any missing or non-callable attributes that are required by iface
    missing = []
    for name, required in iface.__dict__.items():
        # Skip private and special attributes
        if name.startswith("_"):
            continue
        # If the interface has a descriptor or a function, we expect the candidate to provide it
        if callable(required):
            if not hasattr(candidate_cls, name):
                missing.append(name)
            else:
                provided = getattr(candidate_cls, name)
                if not callable(provided):
                    missing.append(name)
        else:
            # For non-callable attributes, we just check presence
            if not hasattr(candidate_cls, name):
                missing.append(name)

    if missing:
        msg = (
            f"Candidate {getattr(candidate_cls, '__name__', repr(candidate_cls))} "
            f"does not provide required members of interface {getattr(iface, '__name__', repr(iface))}: "
            f"{', '.join(missing)}"
        )
        if tentative:
            return False
        raise TypeError(msg)

    return True

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        return default
    for _map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap, self._pb.BoolMap]:
        if key in _map:
            return _map.pop(key)

def popitem(self):
        """Remove and return the `(key, value)` pair most recently used."""
        try:
            key, value = dict.popitem(self)
            return key, value
        except KeyError as e:
            raise KeyError('dict is empty') from e

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dictionary is empty')
    import random
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

def _create_converter(self) -> _converting._Converter:
        """
        Create the parameter style converter.

        Returns the parameter style converter (:class:`._converting._Converter`).
        """
        try:
            converter = _converting._Converter()
            return converter
        except Exception as exc:
            raise RuntimeError("Failed to create converter instance") from exc

def set_cut_chars(self, before: bytes, after: bytes) -> None:
    """Set the bytes used to delimit slice points.

    Args:
        before: Split file before these delimiters.
        after: Split file after these delimiters.
    """
    if not isinstance(before, (bytes, bytearray)):
        raise TypeError(f"'before' must be a bytes-like object, got {type(before).__name__}")
    if not isinstance(after, (bytes, bytearray)):
        raise TypeError(f"'after' must be a bytes-like object, got {type(after).__name__}")
    if len(before) == 0:
        raise ValueError("'before' delimiter cannot be empty")
    if len(after) == 0:
        raise ValueError("'after' delimiter cannot be empty")
    self._cut_before = bytes(before)
    self._cut_after = bytes(after)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request."""
    try:
        path = getattr(request, "path", None)
        if path is None and isinstance(request, dict):
            path = request.get("PATH_INFO") or request.get("path")
        if not path:
            return False
        return path.startswith("/_matrix/")
    except Exception:
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime instance")
    # Ensure the datetime is timezone aware in UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    utc_dt = dt.astimezone(timezone.utc)
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%S.%fZ")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    tag = tag.strip()
    if not tag or len(tag) > 30:
        return False
    allowed_chars = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-")
    return all(ch in allowed_chars for ch in tag)

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.

    The returned dictionary maps a tag (without namespace) to either a single
    Element or a list of Elements when multiple children have the same tag.
    """

    if not hasattr(node, 'getchildren') and not hasattr(node, '__iter__'):
        raise TypeError("node must be an Element or ElementTree")

    # Work with an Element.  ElementTree will yield the root element when
    # iterated.
    if hasattr(node, 'getroot'):
        node = node.getroot()

    result = {}

    for child in node:
        # Strip namespace if present
        tag = child.tag
        if isinstance(tag, str) and '}' in tag:
            tag = tag.split('}', 1)[1]

        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child

    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")
    base = url.rstrip('/')
    path = document_path if document_path else "/nodeinfo/2.0"
    if not path.startswith("/"):
        path = "/" + path
    href = f"{base}{path}"
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON first
        import json
        parsed = json.loads(document)
        return parsed
    except Exception:
        # Fallback to XRD (XML)
        try:
            import xml.etree.ElementTree as ET
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            root = ET.fromstring(document)

            result: Dict[str, object] = {}

            # Extract <Link> elements
            for link in root.findall(".//xrd:Link", ns):
                rel = link.attrib.get("rel")
                href = link.attrib.get("href")
                if rel and href:
                    # If multiple links with same rel, store as list
                    if rel in result:
                        if isinstance(result[rel], list):
                            result[rel].append(href)
                        else:
                            result[rel] = [result[rel], href]
                    else:
                        result[rel] = href

            # Extract <Subject>
            subject = root.find(".//xrd:Subject", ns)
            if subject is not None and subject.text:
                result["subject"] = subject.text

            # Extract other useful elements if needed
            # e.g., <DisplayName> or <Expires>
            for tag in ["DisplayName", "Expires"]:
                element = root.find(f".//xrd:{tag}", ns)
                if element is not None and element.text:
                    result[tag.lower()] = element.text

            return result
        except Exception:
            # If parsing fails, return None to indicate failure
            return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        # Extract host from handle
        host = handle.split("@")[1]
    except Exception:
        return None
    # Encode the resource parameter
    try:
        resource = urllib.parse.quote(f"acct:{handle}")
    except Exception:
        return None
    # Construct the webfinger URL
    url = f"https://{host}/.well-known/webfinger?resource={resource}"
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            if response.status != 200:
                return None
            # Decode as UTF-8, replace errors
            return response.read().decode('utf-8', errors='replace')
    except Exception:
        # Any error (e.g., network, HTTP error) results in no document
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if key is None:
        raise ValueError("key cannot be None")

    # Resolve the full key chain, allowing key to be a sequence itself
    if isinstance(key, (list, tuple)):
        key_chain = list(key)
        key_chain.extend(keys)
    else:
        key_chain = [key] + list(keys)

    if not key_chain:
        raise ValueError("At least one key must be provided")

    current = dic
    for k in key_chain[:-1]:
        if k not in current or not isinstance(current[k], dict):
            current[k] = {}
        current = current[k]
    current[key_chain[-1]] = val
    return dic

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    file_names = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if spec_option is not None and not fname.endswith(spec_option):
                    continue
                full_path = os.path.join(directory, fname)
                if os.path.isfile(full_path):
                    file_names.append(full_path)
        except (OSError, FileNotFoundError):
            continue
    return sorted(file_names)

