@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("No content provided to validate_from_content")
        # attempt YAML loading; YAML may return None for empty content
        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Error parsing YAML content: {exc}") from exc
        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must resolve to a YAML mapping")
        # Define the set of required top-level keys; adjust as needed for the spec
        required_keys = ["metadata", "grading_parameters", "points"]
        missing_keys = [k for k in required_keys if k not in data]
        if missing_keys:
            raise IRValidatorException(
                f"Missing required spec sections: {', '.join(missing_keys)}"
            )
        return data

def validate_from_file(cls, yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    # Ensure a file path was provided
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")

    # Resolve to a Path-like object if a string is provided
    try:
        from pathlib import Path
        yaml_path = Path(yaml_file)
    except Exception as e:
        raise IRValidatorException(f"Invalid file path '{yaml_file}': {e}")

    # Read and parse the YAML file, handling common I/O and syntax errors
    try:
        with yaml_path.open('r', encoding='utf-8') as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise IRValidatorException(f"File not found: {yaml_path}")
    except yaml.YAMLError as ye:
        raise IRValidatorException(f"YAML parsing error in {yaml_path}: {ye}")
    except Exception as e:
        raise IRValidatorException(f"Unexpected error while reading {yaml_path}: {e}")

    # Check that the parsed data is a mapping
    if not isinstance(data, dict):
        raise IRValidatorException(f"Top-level YAML structure in {yaml_path} must be a mapping (dict)")

    # Validate presence of required fields if the class defines them
    required_fields = getattr(cls, 'REQUIRED_FIELDS', None)
    if required_fields:
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing mandatory fields in {yaml_path}: {', '.join(missing)}"
            )

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    import copy
    def _merge_include(section, name, visited=None):
        """
        Recursively merge included sections into the current section.
        """
        if visited is None:
            visited = set()
        if not isinstance(section, dict):
            return
        includes = section.pop('include', None)
        if includes is None:
            return
        if isinstance(includes, str):
            includes = [includes]
        for inc_name in includes:
            # Detect circular references
            cycle_key = f"{name}:{inc_name}"
            if cycle_key in visited:
                raise RuntimeError(f"Circular include detected: {cycle_key}")
            visited.add(cycle_key)
            inc_section = parser_dict.get(inc_name)
            if inc_section is None:
                raise KeyError(f"Included group '{inc_name}' not found in parser_dict")
            # Perform a shallow copy of the included section to avoid mutating the original spec
            for k, v in inc_section.items():
                if k not in section:
                    section[k] = copy.deepcopy(v)
            # After merging the root two levels, dive into any nested includes
            _merge_include(section, f"{name}->{inc_name}", visited)
    # Process every top-level entry in parser_dict
    for key, val in list(parser_dict.items()):
        _merge_include(val, key)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # First try to read values directly from the spec attribute
    try:
        src = getattr(self, 'spec', {})
        if isinstance(src, dict):
            # If spec is a plain dictionary
            defaults.update(src)
        else:
            # Treat spec as an object with attributes
            for key in dir(src):
                if key.startswith('_'):
                    continue
                try:
                    val = getattr(src, key)
                    defaults[key] = val
                except Exception:
                    # Skip attributes that cannot be accessed
                    pass
    except Exception:
        # If accessing spec fails, ignore and continue
        pass

    # Merge in defaults from the _default_spec attribute, if available
    try:
        base = getattr(self, '_default_spec', {})
        if isinstance(base, dict):
            for k, v in base.items():
                defaults.setdefault(k, v)
        else:
            for key in dir(base):
                if key.startswith('_'):
                    continue
                try:
                    val = getattr(base, key)
                    defaults.setdefault(key, val)
                except Exception:
                    pass
    except Exception:
        pass

    return defaults

def get_deprecated_args(self):
    """Return a dict mapping deprecated argument names to their current replacements."""
    return {}

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input type
    if command_name is None:
        raise ValueError("command_name must not be None")
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if command_name.strip() == "":
        raise ValueError("command_name must not be an empty string")

    # Retrieve the internal registry of options if it exists
    registry = getattr(self, "_command_options", None)
    if registry is None:
        raise RuntimeError("Command options registry not initialized")
    if not isinstance(registry, dict):
        raise RuntimeError("Command options registry should be a dict mapping names to option lists")

    # Attempt to find the exact key
    if command_name in registry:
        opts = registry[command_name]
    else:
        # Try a case-insensitive match as a fallback
        matched_key = None
        for key in registry:
            if key.lower() == command_name.lower():
                matched_key = key
                break
        if matched_key is not None:
            opts = registry[matched_key]
        else:
            # No match found
            raise KeyError(f"Command '{command_name}' not found in options registry")

    # Ensure the returned value is a list; if it's a tuple or set, convert to list
    if isinstance(opts, (tuple, set)):
        opts = list(opts)
    if not isinstance(opts, list):
        raise RuntimeError("Options for command should be a list or tuple in the registry")

    # Return a shallow copy to prevent accidental modification of the registry
    return list(opts)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")
    # Retrieve the command specification; raise if missing
    try:
        command_spec = self.commands[command_name]
    except AttributeError:
        raise AttributeError("The object does not have a 'commands' attribute")
    except KeyError:
        raise KeyError(f"Command '{command_name}' not found")
    # The command spec may be a dict of options or an object with an 'options' dict
    if isinstance(command_spec, dict):
        options = command_spec.get("options", command_spec)
    else:
        options = getattr(command_spec, "options", None)
        if options is None:
            # fall back to treating the command spec itself as the options mapping
            options = command_spec
    # Ensure we have a mapping to index by argument_name
    if not isinstance(options, dict):
        raise TypeError(f"Options for command '{command_name}' are not a dictionary")
    # Retrieve the argument specification; raise if missing
    try:
        arg_spec = options[argument_name]
    except KeyError:
        raise KeyError(f"Argument '{argument_name}' not found in command '{command_name}'")
    return arg_spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if not args:
        return []

    # determine the source of arguments
    if hasattr(args, "__dict__"):
        arg_dict = vars(args)
    elif isinstance(args, dict):
        arg_dict = args
    else:
        # try to interpret as an iterable of items (name, value) or names
        arg_dict = {}
        for item in args:
            if isinstance(item, tuple) and len(item) == 2:
                name, val = item
                arg_dict[name] = val
            else:
                arg_dict[item] = None

    silent = []

    for name, val in arg_dict.items():
        # consider silent if:
        # 1. the value is None or False
        # 2. or the argument name starts with an underscore
        if val is None or val is False or name.startswith("_"):
            silent.append(name)

    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    required = getattr(self, 'required', [])
    if not required:
        return
    if isinstance(args, dict):
        missing = [name for name in required
                   if name not in args or args[name] is None]
    else:
        # Assume a positional sequence, missing arguments are those beyond the
        # supplied count.
        missing = [required[i] for i in range(len(args), len(required))]
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = set()
    # Normalize inputs
    if options_spec is None:
        return list(required)
    for opt in options_spec:
        # Each option expected to be a mapping
        if not isinstance(opt, dict):
            continue
        req_when = opt.get('required_when')
        if not req_when:
            continue
        # Determine option name
        opt_name = opt.get('arg') or opt.get('name') or opt.get('id')
        if not opt_name:
            continue  # skip if no identifiable name
        try:
            # If callable, invoke with command_name and args
            if callable(req_when):
                if req_when(command_name, args):
                    required.add(opt_name)
                continue
            # If dict, interpret common patterns
            if isinstance(req_when, dict):
                # pattern { 'command': ['cmd1', 'cmd2'] }
                cmd_list = req_when.get('command') or req_when.get('commands')
                if cmd_list:
                    if command_name in cmd_list:
                        required.add(opt_name)
                        continue
                # fallback: if key matches command_name
                if command_name in req_when:
                    required.add(opt_name)
                    continue
            # If iterable of conditions
            if isinstance(req_when, (list, tuple, set)):
                for cond in req_when:
                    if callable(cond):
                        if cond(command_name, args):
                            required.add(opt_name)
                            break
                    elif isinstance(cond, dict):
                        cmd_list = cond.get('command') or cond.get('commands')
                        if cmd_list and command_name in cmd_list:
                            required.add(opt_name)
                            break
        except Exception:
            # silently ignore any mis-evaluated condition
            continue
    return list(required)

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument name to attributes")

    for name, attrs in args.items():
        # Expect attrs to be a mapping containing 'value' and 'max_length'
        if not isinstance(attrs, dict):
            continue
        if 'value' not in attrs or 'max_length' not in attrs:
            continue
        value = attrs['value']
        max_len = attrs['max_length']
        try:
            length = len(value)
        except (TypeError, AttributeError):
            # Value is not a sized object; skip validation
            continue
        if length > max_len:
            raise ValueError(
                f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Accept either a dict or a list of (name, value) tuples.
    if isinstance(args, list):
        try:
            args = dict(args)
        except Exception:
            raise ValueError("args list must contain key/value pairs")
    if not isinstance(args, dict):
        raise TypeError("args must be a dict or list of tuples")

    # Determine the argument specification.  A concrete subclass might
    # provide it under a known attribute; fall back to a generic name.
    arg_spec = getattr(self, "argument_spec", None)
    if arg_spec is None:
        arg_spec = getattr(self, "parsed_yaml", {}).get("args", {})
    if not isinstance(arg_spec, dict):
        # The spec is malformed; nothing to validate.
        return

    for name, spec in arg_spec.items():
        if not isinstance(spec, dict):
            # Malformed spec entry; skip.
            continue
        choices = spec.get("choices")
        if not choices:
            continue
        if name not in args:
            # Argument not supplied; nothing to check.
            continue
        value = args[name]
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{name}': {value!r}. "
                f"Expected one of: {choices}"
            )
    # If we get here, all choice arguments are valid. No return value needed.

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :raises TypeError: If ``args`` is not a dict or a sequence of length 3.
    :raises ValueError: If the value is not within the specified bounds.
    :return: The original value if it is within bounds.
    """
    # Extract the value, minimum and maximum from various possible arg formats
    if isinstance(args, dict):
        value = args.get('value')
        min_val = args.get('min')
        max_val = args.get('max')
        # allow alternative key names
        if min_val is None and 'min_' in args:
            min_val = args['min_']
        if max_val is None and 'max_' in args:
            max_val = args['max_']
        if value is None:
            raise TypeError(
                "Dictionary 'args' must contain a 'value' key to validate")
    else:
        # Assume a sequence of length three: (value, min, max)
        try:
            value, min_val, max_val = args
        except Exception as exc:
            raise TypeError(
                "args must be a dict with 'value' or a sequence of "
                "length three (value, min, max)"
            ) from exc

    # If bounds were not provided, nothing to validate
    if min_val is None and max_val is None:
        return value

    # Validate that min <= max when both are defined
    if min_val is not None and max_val is not None:
        try:
            if min_val > max_val:
                raise ValueError(
                    f"minimum ({min_val}) must not be greater than maximum ({max_val})")
        except TypeError as exc:
            raise TypeError(
                "minimum and maximum must be comparable values"
            ) from exc

    # Perform boundary checks
    if min_val is not None:
        try:
            if value < min_val:
                raise ValueError(
                    f"value ({value}) is less than minimum ({min_val})")
        except TypeError as exc:
            raise TypeError(
                "value and minimum must be comparable"
            ) from exc

    if max_val is not None:
        try:
            if value > max_val:
                raise ValueError(
                    f"value ({value}) is greater than maximum ({max_val})")
        except TypeError as exc:
            raise TypeError(
                "value and maximum must be comparable"
            ) from exc

    return value

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Accept both dicts and iterable of pairs
    if args is None:
        raise ValueError("args must not be None")
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception as exc:  # pragma: no cover
            raise TypeError("args must be a dict or an iterable of (key, value) pairs") from exc

    # Determine control keys: first look for a predefined set on the instance
    control_keys = set()
    if hasattr(self, "control_keys") and isinstance(self.control_keys, (set, list)):
        control_keys.update(self.control_keys)
    if hasattr(self, "control_args") and isinstance(self.control_args, (set, list)):
        control_keys.update(self.control_args)

    # By convention a leading underscore marks a control argument
    for k in list(args):
        if isinstance(k, str) and k.startswith("_"):
            control_keys.add(k)

    # Split into control and nested (including custom) dictionaries
    control_args = {}
    nested_args = {}
    for k, v in args.items():
        if k in control_keys:
            control_args[k] = v
        else:
            nested_args[k] = v

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated dictionary
    """
    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    elif not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list or dictionary")

    for item in extra_vars:
        if not isinstance(item, dict):
            raise ValueError("each extra_var must be a dictionary")
        vars_dict.update(item)

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")
    # Retrieve the parser configuration for the given command name.
    parser_cfg = getattr(self, "parsers", {}).get(parser_name)
    if parser_cfg is None:
        raise KeyError(f"Unknown parser '{parser_name}'")
    # Iterate over each option definition in the parser configuration.
    for opt in getattr(parser_cfg, "options", []):
        opt_name = getattr(opt, "name")
        if opt_name is None:
            continue  # Skip malformed option definitions.
        # Convert if the argument is present.
        if opt_name in values_dict:
            try:
                values_dict[opt_name] = opt.convert(values_dict[opt_name])
            except Exception as exc:
                raise ValueError(
                    f"Cannot convert argument '{opt_name}' for parser '{parser_name}': {exc}"
                ) from exc
        # If the argument is missing but a default exists, apply it.
        else:
            if getattr(opt, "default", None) is not None:
                values_dict[opt_name] = opt.convert(opt.default)
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(current, parent_key='', result=None):
        if result is None:
            result = {}
        if isinstance(current, dict):
            for k, v in current.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key, result)
        elif isinstance(current, list):
            for idx, item in enumerate(current):
                new_key = f"{parent_key}.{idx}" if parent_key else str(idx)
                _flatten(item, new_key, result)
        else:
            result[parent_key] = current
        return result

    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    spec_path = os.path.join(plugin_dir, "plugin.json")
    if not os.path.isfile(spec_path):
        # try alternatives if needed
        raise FileNotFoundError(f"Plugin spec file not found in {plugin_dir}")

    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            spec_data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in plugin spec: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Error reading plugin spec: {e}") from e

    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    # Determine the environment variable name and the config path value.
    env_var = getattr(self, 'config_envvar', 'CONFIG_PATH')
    try:
        # Get the current value if the environment variable is already set.
        current_value = os.getenv(env_var)
    except Exception:
        # If os.getenv raises an unexpected error, treat it as unset.
        current_value = None

    # Only set the variable if it is not already defined or is empty.
    if not current_value:
        try:
            # Retrieve the config path from the instance.
            path = getattr(self, 'config_path')
            if not path:
                raise ValueError('Missing config_path attribute.')

            # If the path is a pathlib.Path, get its string representation.
            if isinstance(path, (str, bytes)):
                path_str = str(path)
            else:
                path_str = str(path)

            # If an os.path module is available, verify that the path exists.
            if hasattr(os, 'path'):
                if not os.path.exists(path_str):
                    raise FileNotFoundError(f'Config path does not exist: {path_str}')

            # Inject into the environment.
            os.environ[env_var] = path_str
        except Exception:
            # Silently ignore failures; caller can inspect the environment if needed.
            pass
    return None
